function focus(cy, idOrPrefix) {
  const node = cy.getElementById(idOrPrefix);
  if (node && node.nonempty()) {
    cy.animate({ center: { eles: node }, zoom: 1.4 }, { duration: 200 });
    return;
  }
  const matches2 = cy.nodes().filter((candidate) => candidate.id().startsWith(idOrPrefix));
  if (matches2.nonempty()) {
    cy.fit(matches2, 60);
  }
}
function zoomIn(cy) {
  cy.zoom({ level: cy.zoom() * 1.2, renderedPosition: { x: cy.width() / 2, y: cy.height() / 2 } });
}
function zoomOut(cy) {
  cy.zoom({ level: cy.zoom() / 1.2, renderedPosition: { x: cy.width() / 2, y: cy.height() / 2 } });
}

